<div class="section-head"><div><h2>Manage clarifications</h2><p class="muted">Answer questions for contests you own.</p></div></div><section class="grid"><?php foreach($clarifications as $cl):?><article class="card"><div class="section-head"><div><span class="eyebrow"><?=e($cl['contest_title'])?></span><h3><?=e($cl['question'])?></h3><p class="muted">Asked by <?=e($cl['asker_name'])?> · <?=e($cl['asked_at'])?></p></div><span class="badge badge-<?=e(strtolower($cl['clarification_status']))?>"><?=e($cl['clarification_status'])?></span></div><?php if($cl['answer']):?><p><strong>Answer:</strong> <?=e($cl['answer'])?></p><?php else:?><form class="form-grid" method="post" action="<?=e(url('/organizer/clarifications/'.$cl['clarification_id'].'/answer'))?>"><?=csrf_field()?><div class="field field-full"><label for="answer-<?=e($cl['clarification_id'])?>">Answer</label><textarea id="answer-<?=e($cl['clarification_id'])?>" name="answer" required></textarea></div><label class="check"><input type="checkbox" name="is_public" value="Y"> Show to all participants</label><button class="button">Answer question</button></form><?php endif;?></article><?php endforeach;?><?php if(!$clarifications):?><article class="card empty">No clarification requests.</article><?php endif;?></section>
